import { sql } from 'drizzle-orm';
import { type AnyPgColumn, boolean, check, index, integer, text, uuid } from 'drizzle-orm/pg-core';
import {
  appointmentRequestedViaOptions,
  appointmentStatuses,
  callLogDirections,
  gatePassKinds,
  gatePassRequestedViaOptions,
  gatePassStatuses,
  postalLogDirections,
  visitorPurposes,
} from '@takhti/contracts';
import { baseColumns, branchIdColumn } from '../../kernel/base-columns';
import { dateStr, enumText, timestamptz, timeStr } from '../../kernel/columns';
import { defineTable } from '../../kernel/define-table';
import { profiles } from '../identity/identity.table';
import { rooms } from '../organisation/organisation.table';
import { files } from '../shared/files.table';
import { staff } from '../staff/staff.table';
import { guardians, students } from '../students/students.table';

/* The tables of M09 · Front office. */

export const visitors = defineTable(
  'visitors',
  { module: 'M09', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    fullName: text().notNull(),
    phone: text(),
    /** sensitive */
    cnic: text(),
    purpose: enumText(visitorPurposes).notNull(),
    purposeDetail: text(),
    /** whom they came to see */
    hostStaffId: uuid().references((): AnyPgColumn => staff.id),
    /** a parent visiting about a child */
    studentId: uuid().references((): AnyPgColumn => students.id),
    vehicleNo: text(),
    badgeNo: text(),
    photoFileId: uuid().references((): AnyPgColumn => files.id),
    checkedInAt: timestamptz().notNull(),
    checkedOutAt: timestamptz(),
    /** left without checking out, or a concern */
    isFlagged: boolean().notNull().default(false),
    notes: text(),
  },
  (t) => [
    check('visitors_checked_out_at_from', sql`${t.checkedOutAt} >= ${t.checkedInAt}`),
    index('visitors_branch_checked_in_at_idx').on(t.orgId, t.branchId, t.checkedInAt),
    index('visitors_full_name_trgm').using('gin', sql`${t.fullName} gin_trgm_ops`),
  ],
);

/** Permission for a student to leave during school hours. */
export const gatePasses = defineTable(
  'gate_passes',
  {
    module: 'M09',
    scope: 'branch',
    family: 'studentId',
    familyRule: { read: true, insert: { status: 'requested' } },
  },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    passDate: dateStr().notNull(),
    kind: enumText(gatePassKinds).notNull(),
    reason: text().notNull(),
    requestedVia: enumText(gatePassRequestedViaOptions).notNull().default('staff'),
    /** an authorised guardian */
    pickupGuardianId: uuid().references((): AnyPgColumn => guardians.id),
    /** who will collect */
    pickupName: text().notNull(),
    pickupRelation: text().notNull(),
    /** required when the person is not a registered guardian */
    pickupCnic: text(),
    leaveTime: timeStr().notNull(),
    /** temporary exit */
    returnExpectedTime: timeStr(),
    /** a 4-digit code the guardian shows at the gate */
    verificationCodeHash: text().notNull(),
    status: enumText(gatePassStatuses).notNull().default('requested'),
    decidedBy: uuid().references((): AnyPgColumn => profiles.id),
    exitedAt: timestamptz(),
    exitRecordedBy: uuid().references((): AnyPgColumn => profiles.id),
    returnedAt: timestamptz(),
  },
  (t) => [
    check(
      'gate_passes_pickup_cnic_needed',
      sql`${t.pickupGuardianId} is not null or ${t.pickupCnic} is not null`,
    ),
    index('gate_passes_branch_pass_date_status_idx').on(t.orgId, t.branchId, t.passDate, t.status),
  ],
);

export const callLogs = defineTable(
  'call_logs',
  { module: 'M09', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    direction: enumText(callLogDirections).notNull(),
    callerName: text().notNull(),
    phone: text(),
    regarding: text().notNull(),
    studentId: uuid().references((): AnyPgColumn => students.id),
    calledAt: timestamptz().notNull(),
    durationMinutes: integer(),
    followUpOn: dateStr(),
    isFollowUpDone: boolean().notNull().default(false),
    note: text(),
  },
);

export const postalLogs = defineTable(
  'postal_logs',
  { module: 'M09', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    direction: enumText(postalLogDirections).notNull(),
    loggedOn: dateStr().notNull(),
    /** from or to */
    party: text().notNull(),
    subject: text().notNull(),
    referenceNo: text(),
    courier: text(),
    trackingNo: text(),
    addressedToStaffId: uuid().references((): AnyPgColumn => staff.id),
    handedTo: text(),
    handedAt: timestamptz(),
    /** a scan */
    fileId: uuid().references((): AnyPgColumn => files.id),
  },
);

export const appointments = defineTable(
  'appointments',
  {
    module: 'M09',
    scope: 'branch',
    family: 'studentId',
    familyRule: { read: true, insert: { status: 'requested' } },
  },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    /** whom the meeting is with */
    staffId: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    guardianId: uuid().references((): AnyPgColumn => guardians.id),
    studentId: uuid().references((): AnyPgColumn => students.id),
    visitorName: text().notNull(),
    phone: text(),
    purpose: text().notNull(),
    startsAt: timestamptz().notNull(),
    endsAt: timestamptz().notNull(),
    roomId: uuid().references((): AnyPgColumn => rooms.id),
    requestedVia: enumText(appointmentRequestedViaOptions).notNull().default('staff'),
    status: enumText(appointmentStatuses).notNull().default('requested'),
    note: text(),
  },
  (t) => [check('appointments_ends_at_after', sql`${t.endsAt} > ${t.startsAt}`)],
);
